"""Debates sobre os fundamentos da ética (quinta leva): origem da moral, critério mais sólido, verdade moral, razão ou sentimento, por que ser moral, consequências ou princípios."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
TEMAS_DB5 = ['Fundamentos da ética']
FE = TEMAS_DB5[0]

DEBATES5 = [
dict(s='origem-da-moral', n='De onde vem a moral?', t=FE, r='Deus, a natureza, a razão, o sentimento ou a convenção? As respostas sobre a origem da moral, e por que a origem não decide o conteúdo.',
 v='Toda cultura tem moral, e as pessoas discordam sobre de onde ela vem. A pergunta tem duas camadas que se misturam: a origem histórica e psicológica (como a moral surgiu em nós) e a fonte da autoridade (o que faz uma regra moral valer). Confundir as duas é a fonte de muitos erros.',
 lados=[('As respostas', ['Deus ou a ordem sagrada: a moral é dada por revelação ou pela ordem do cosmos (dharma). É a resposta mais antiga e mais difundida; o dilema de Eutífron pergunta se o bem é bom porque Deus manda, ou se Deus manda porque é bom.', 'A natureza e a evolução: a moral é um conjunto de disposições que a seleção natural favoreceu em animais sociais, refinado pela cultura. Explica a origem; não diz quais disposições seguir.', 'A razão: a moral é o que todo agente racional precisa aceitar (Kant), ou o que agentes racionais acordariam (contratualismo). Explica a autoridade; precisa explicar a motivação.', 'O sentimento: a moral nasce da simpatia e das emoções morais (Hume, Smith), estendidas pela imparcialidade. Explica a motivação; precisa de um corretivo para a parcialidade.', 'A convenção: a moral é o acordo de cada sociedade (relativismo). Explica a variação; não explica o desacordo nem o progresso.'])],
 c=['Explicar como a moral surgiu em nós (evolução, cultura) não diz se ela está certa: é a falácia genética. A origem de uma crença não decide seu valor, como a origem da matemática não decide a verdade de um teorema.', 'A fonte da autoridade é uma pergunta de metaética, e as respostas (realismo, construtivismo, expressivismo) não coincidem com as da origem histórica.', 'Religiosos e não religiosos convergem em quase todo o conteúdo moral básico, o que sugere que a origem religiosa, mesmo quando real, não é a única via de acesso.'],
 p=('parcial', 'Sobre a origem histórica e psicológica, a resposta mais apoiada é a evolução refinada pela cultura, e há convergência entre ciência e filosofia. Sobre a fonte da autoridade, o debate é real entre razão, sentimento e fatos morais; o que a maioria rejeita é a convenção pura (relativismo) e a ideia de que a moral seria arbitrária se viesse de um mandamento. O que todos deveriam aceitar: saber de onde a moral veio não diz o que fazer com ela.'),
 teorias=[('teoria-do-mandamento-divino', 'Mandamento divino', 'A moral vem de Deus; a versão modificada diz que vem da natureza boa de Deus.'), ('realismo-naturalista', 'Realismo naturalista', 'Fatos morais são fatos sobre bem-estar e florescimento, descobertos como outros fatos.'), ('construtivismo', 'Construtivismo', 'A moral é o que agentes racionais construiriam em condições ideais.'), ('emotivismo', 'Emotivismo', 'A moral vem das atitudes que expressamos; não há fonte além delas.'), ('relativismo-cultural', 'Relativismo cultural', 'Vem da convenção de cada sociedade.'), ('intuicionismo-moral', 'Intuicionismo', 'Conhecemos verdades morais básicas diretamente, por intuição racional.')],
 licoes=['etica-e-religiao', 'evolucao-e-moral', 'o-que-e-metaetica', 'fatos-e-valores'],
 fx=[('Metaethics (Stanford Encyclopedia)', SEP + 'metaethics/'), ('Morality and Evolutionary Biology (Stanford Encyclopedia)', SEP + 'morality-biology/'), ('Religion and Morality (Stanford Encyclopedia)', SEP + 'religion-morality/')]),

dict(s='criterio-mais-solido', n='Qual é o critério moral mais sólido?', t=FE, r='Regra de ouro, véu da ignorância, universalidade, coerência, justiça, imparcialidade: são testes diferentes, e todos apontam na mesma direção.',
 v='Diante de uma regra moral, como saber se ela é boa? A filosofia produziu vários testes: a regra de ouro, o imperativo de Kant, o véu de Rawls, a universalizabilidade de Hare, a coerência de Rawls e Sidgwick, a igual consideração de Singer. Qual é o mais sólido, e eles concordam?',
 lados=[('Os critérios e o que cada um testa', ['Regra de ouro: trate os outros como gostaria de ser tratado. Intuitiva e universal entre culturas; falha quando os outros não querem o que você quer, e por isso a versão melhor pergunta o que o outro tem razão de querer.', 'Universalidade (Kant, Hare): a regra deve valer para todos em situação igual, inclusive para você e seu adversário. Elimina exceções em causa própria; não diz qual regra escolher entre as universalizáveis.', 'Véu da ignorância (Rawls): escolha as regras sem saber quem você será. Retira o interesse próprio da decisão; depende de como se modela a escolha.', 'Coerência (equilíbrio reflexivo): casos iguais pedem tratamento igual, a menos que haja diferença relevante. É o motor de todo progresso moral; só funciona com bons casos para comparar.', 'Justiça (dar a cada um o que lhe é devido): o critério mais antigo; precisa de uma teoria do que é devido.', 'Imparcialidade e igual consideração (Sidgwick, Singer): interesses iguais contam igual, seja de quem forem. É o que os outros critérios tentam formular.']),
        ('Para onde eles convergem', ['Todos são formas de remover a parcialidade: a exceção que você faz para si, para os seus, para o seu grupo.', 'Aplicados com honestidade, todos perguntam a mesma coisa: que diferença relevante justifica tratar este caso de forma diferente?', 'Levados até o fim, levam ao critério mais abrangente: se o que importa é poder ser prejudicado ou beneficiado, o círculo inclui todos os seres sencientes, e nenhum traço (cor, sexo, nação, espécie) serve para excluir.', 'Rowlands mostrou isso com o véu: se esconde talento e classe, deve esconder a espécie. Singer, com a igual consideração: a dor é dor, seja de quem for.'])],
 c=['Os critérios não eliminam os valores: duas pessoas podem passar pelo véu e escolher diferente conforme o quanto temem o risco.', 'Eles eliminam visões ruins com mais facilidade do que confirmam as boas; passar no teste não prova que está certo.', 'Podem ser usados de má-fé, para confirmar o que já se pensava; o antídoto é aplicá-los aos próprios pontos cegos.'],
 p=('forte', 'Os critérios são formulações de uma mesma exigência, a imparcialidade: casos iguais, tratamento igual, salvo diferença relevante. Nenhum é “o mais sólido” isoladamente; o mais sólido é o uso combinado, e ele converge. Quando se pergunta qual é a diferença relevante entre quem sofre, nenhuma das fronteiras tradicionais resiste, e o critério mais abrangente, a igual consideração de todos os seres sencientes, é o que sobra. O desacordo real fica sobre graus e sobre como pesar, não sobre quem entra.'),
 teorias=[('sencientismo', 'Sencientismo', 'O ponto de chegada: quem pode ser prejudicado ou beneficiado conta, sem traço que exclua.'), ('deontologia-kantiana', 'Kant', 'A universalizabilidade como teste de toda máxima.'), ('contratualismo-rawlsiano', 'Rawls', 'O véu como procedimento de imparcialidade.'), ('contratualismo-estendido', 'Rowlands', 'O véu levado até a espécie.'), ('prescritivismo', 'Hare', 'Universalizar é pesar as preferências de todos como as próprias.'), ('utilitarismo-classico', 'Sidgwick e Singer', 'O ponto de vista do universo: cada um conta por um.')],
 licoes=['imparcialidade', 'argumentos-morais', 'igualdade-humana', 'circulo-moral', 'especismo'],
 fx=[('Impartiality (Stanford Encyclopedia)', SEP + 'impartiality/'), ('Universalizability (Wikipédia)', WE + 'Universalizability'), ('Como testar sua visão moral (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/testar-visao-moral.html'), ('Mapa do Teste de Visão Moral', 'https://ethicstest.biblioverse.org/map.html')]),

dict(s='existe-verdade-moral', n='Existe verdade moral?', t=FE, r='“A tortura é errada” é verdadeiro como “a água ferve a 100 graus”? Realistas dizem que sim; antirrealistas, que a frase faz outra coisa. O que está em jogo.',
 v='É a pergunta central da metaética. Se há verdades morais, podemos estar errados sobre elas e descobri-las; se não há, dizer que algo é errado expressa, prescreve ou inventa. A resposta não decide o que fazer, mas decide o que estamos fazendo ao discutir.',
 lados=[('Há verdades morais (realismo e objetivismo)', ['A experiência moral se parece com descobrir, não com inventar: quem muda de ideia sobre a escravidão sente que aprendeu.', 'Convergência: em condições de informação e imparcialidade, as pessoas concordam em muito, o que sugere que respondem a algo.', 'Paridade com a lógica e a matemática: rejeitar verdades normativas exigiria rejeitar o que diz o que devemos inferir.', 'O custo da negação: se nada é mesmo errado, o genocídio não é mesmo errado, e isso é mais implausível do que qualquer problema do realismo.']),
        ('Não há, ou a pergunta está mal posta (antirrealismo e quietismo)', ['Estranheza: que tipo de fato obriga só por ser conhecido? Nada no mundo físico funciona assim (Mackie).', 'Desacordo persistente, inclusive entre especialistas; a evolução moldou intuições para sobreviver, não para rastrear verdades (Street).', 'Economia: toda a prática moral se explica por atitudes, sem fatos extras; e o quase-realismo preserva a fala de “verdade” e “erro”.', 'Quietismo: perguntar se fatos morais existem “lá fora” importa um modelo da física para onde ele não cabe; a prática moral funciona sem esse aval.'])],
 c=['A diferença prática entre as posições é menor do que parece: realistas e quase-realistas discutem, corrigem e progridem do mesmo jeito.', 'O objetivismo moral (há verdades que valem para todos) é compatível com o realismo, com o construtivismo e com o expressivismo sofisticado; o que ele exclui é o relativismo.', 'Muita divergência atribuída a “valores” é sobre fatos e sobre quem conta.'],
 p=('aberto', 'É um dos debates mais vivos da filosofia, sem consenso: o realismo não naturalista voltou com força (Parfit, Enoch), e o expressivismo sofisticado responde a cada objeção. O que há de convergência: quase todos rejeitam o relativismo e o subjetivismo simples, e quase todos aceitam que a prática de argumentar, corrigir e progredir faz sentido em qualquer das posições. A pergunta “o que fazer?” sobrevive à metaética inteira.'),
 teorias=[('realismo-nao-naturalista', 'Realismo não naturalista', 'Há fatos morais de um tipo próprio, como os matemáticos.'), ('realismo-naturalista', 'Realismo naturalista', 'Há fatos morais, e são fatos naturais sobre bem-estar.'), ('teoria-do-erro', 'Teoria do erro', 'A linguagem moral tenta descrever fatos que não existem.'), ('quase-realismo', 'Quase-realismo', 'Expressamos atitudes, mas temos direito a falar de verdade e erro.'), ('quietismo-metaetico', 'Quietismo', 'A pergunta está mal colocada.'), ('objetivismo-moral', 'Objetivismo moral', 'Há verdades que valem para todos, seja qual for a explicação.')],
 licoes=['o-que-e-metaetica', 'realismo-moral', 'antirrealismo-moral', 'relativismo-e-quietismo'],
 fx=[('Moral Realism (Stanford Encyclopedia)', SEP + 'moral-realism/'), ('Moral Anti-Realism (Stanford Encyclopedia)', SEP + 'moral-anti-realism/'), ('On What Matters', 'https://www.google.com/search?tbm=bks&q=Parfit+On+What+Matters')]),

dict(s='razao-ou-sentimento', n='Razão ou sentimento: o que fundamenta o juízo moral?', t=FE, r='Hume disse que a razão é escrava das paixões; Kant, que a moral vem da razão pura. A psicologia moderna deu razão a Hume na descrição, e a ética insiste em Kant na correção.',
 v='Quando julgamos que algo é errado, o que está operando: um raciocínio ou um sentimento? A resposta decide como se discute ética, como se educa e quanto se pode confiar no que “parece” certo.',
 lados=[('Sentimento (Hume, Smith, a psicologia moral)', ['A razão sozinha não motiva: você pode saber tudo sobre um ato e não se importar; é a simpatia que move.', 'Haidt e Greene: julgamos primeiro por intuição e emoção, e a razão justifica depois; o “condutor” serve ao “elefante”.', 'Sem emoção moral, o conhecimento não vira conduta: psicopatas raciocinam bem sobre moral e não a sentem.', 'Adam Smith: o espectador imparcial é um sentimento refinado, não uma dedução.']),
        ('Razão (Kant, Sidgwick, racionalistas)', ['Sentimentos são parciais e variáveis; se a moral fosse só sentimento, não haveria como criticar o sentimento errado (nojo, favoritismo).', 'O progresso moral veio de argumentos que mostraram incoerências, não de mudanças de humor.', 'A universalidade e a coerência são operações da razão; é ela que estende a simpatia a quem não sentimos.', 'Explicar como julgamos (psicologia) não diz como devemos julgar (ética): a descrição humeana não refuta a prescrição kantiana.'])],
 c=['Os dois lados respondem a perguntas diferentes: o sentimento explica a motivação e a origem; a razão explica a correção e a extensão.', 'Nussbaum e outros dissolvem a oposição: emoções são juízos sobre o que importa, e podem ser corretas ou incorretas, educadas pela razão.', 'A posição de Singer: a imparcialidade é uma conclusão da razão que a evolução não explica, e por isso merece mais confiança do que as intuições parciais.'],
 p=('parcial', 'Na descrição de como julgamos, Hume venceu: a psicologia confirma que a emoção vem primeiro. Na pergunta sobre como devemos julgar, a razão tem o papel que Kant lhe deu: corrigir, estender e universalizar o que o sentimento começa. A posição mais defendida hoje é a síntese: sentimentos morais educados pela razão, e razão motivada pelo sentimento; nenhum dos dois basta sozinho.'),
 teorias=[('emotivismo', 'Emotivismo', 'A moral é expressão de sentimento; a razão só organiza.'), ('deontologia-kantiana', 'Kant', 'A moral vem da razão pura prática; sentimentos são contingentes.'), ('realismo-naturalista', 'Naturalismo humeano (Hume, Smith)', 'A moral nasce da simpatia e se refina pelo espectador imparcial.'), ('intuicionismo-moral', 'Intuicionismo', 'Intuições racionais, não sentimentos, são a fonte do conhecimento moral.'), ('etica-das-virtudes', 'Virtudes', 'A pessoa boa sente o que deve sentir: emoção e razão formadas juntas pelo hábito.')],
 licoes=['psicologia-moral', 'emocoes-morais', 'evolucao-e-moral', 'kant-e-o-imperativo-categorico'],
 fx=[('Hume’s Moral Philosophy (Stanford Encyclopedia)', SEP + 'hume-moral/'), ('Moral Psychology: Empirical Approaches (Stanford Encyclopedia)', SEP + 'moral-psych-emp/'), ('A Mente Moralista', WE + 'The_Righteous_Mind')]),

dict(s='por-que-ser-moral', n='Por que ser moral?', t=FE, r='Se ninguém visse, você seria justo? A pergunta de Gláucon a Sócrates, e as respostas de 2.400 anos.',
 v='Gláucon, na República, desafia Sócrates: as pessoas são justas por medo de serem pegas; com o anel de Giges, que torna invisível, ninguém o seria. Por que ser moral quando não compensa? A pergunta tem duas versões: por que eu, agora, neste caso; e por que qualquer um, em geral.',
 lados=[('Porque compensa, no fim', ['Platão: a alma injusta vive em desordem; a justiça é saúde da alma, e vale por si mesma, com ou sem anel.', 'Aristóteles e os estoicos: a virtude é parte do florescimento; o injusto não vive bem, mesmo que viva rico.', 'Hobbes e o contratualismo: a cooperação é racional, e quem trapaceia perde a confiança de que depende.', 'Psicologia: pessoas que agem bem relatam mais bem-estar; a culpa e a dissimulação custam.']),
        ('Porque é certo, compense ou não', ['Kant: a moral obriga incondicionalmente; perguntar “o que ganho?” já é sair da moral.', 'Prichard: a pergunta “por que ser moral?” é um erro; ou se vê que se deve, ou nenhum argumento de interesse convencerá, porque transformaria a moral em prudência.', 'Sidgwick admitiu o dualismo da razão prática: a razão não prova que o egoísta erra; o que ela mostra é que o ponto de vista do universo é tão racional quanto o dele.', 'A resposta de interesse falha nos casos que importam: o sacrifício pelo estranho, o ato bom que ninguém verá.'])],
 c=['Há diferença entre justificar a moral para quem já está dentro dela (fácil) e para o egoísta consistente (talvez impossível): nenhum argumento move quem não aceita que os outros contam.', 'A pergunta pode ser sobre motivação (o que me move) ou sobre justificação (o que a torna devida); as respostas são diferentes.', 'Educação moral existe porque a resposta não vem só de argumentos: vem de hábito, exemplo e relações.'],
 p=('parcial', 'A filosofia converge em que a moral não se reduz ao interesse próprio: as respostas de interesse valem para o mundo em geral e falham nos casos cruciais. A posição majoritária é a de Prichard e Kant: ser moral é devido porque os outros contam, e quem pergunta “o que ganho?” já mudou de assunto. O que fica em aberto é o dualismo de Sidgwick: a razão sozinha talvez não refute o egoísta; o que o refuta é a imparcialidade, que ele não aceita.'),
 teorias=[('egoismo-etico', 'Egoísmo ético', 'Só se compensar; e o anel mostra que às vezes não compensa.'), ('etica-das-virtudes', 'Virtudes (Platão, Aristóteles)', 'A justiça é parte da vida boa, com ou sem anel.'), ('contratualismo-hobbesiano', 'Hobbes', 'Cooperar é racional; quem pode trapacear impune é o problema da teoria.'), ('deontologia-kantiana', 'Kant', 'A moral obriga incondicionalmente; não há “por quê” fora dela.'), ('utilitarismo-classico', 'Sidgwick', 'O ponto de vista do universo é racional; o dualismo fica.')],
 licoes=['egoismo-relativismo-e-ceticismo', 'imparcialidade', 'fraqueza-de-vontade', 'aristoteles-e-as-virtudes'],
 fx=[('Ring of Gyges (Wikipédia)', WE + 'Ring_of_Gyges'), ('Does Moral Philosophy Rest on a Mistake?', WE + 'H._A._Prichard'), ('Os Métodos da Ética', 'https://www.gutenberg.org/ebooks/46743')]),
]
assert len({d['s'] for d in DEBATES5}) == len(DEBATES5)
